 sealed class DesktopContext:ApplicationContext {
  readonly Engine engine;readonly MainWindow window;readonly NotifyIcon tray;readonly NodeMonitor monitor;readonly FloatingWindow floating;readonly EventWaitHandle show,remove,exit,launch;readonly System.Windows.Forms.Timer tick;int lastTicket,lastAlert;bool forceNotified;
  public DesktopContext(bool background,EventWaitHandle open){show=open;launch=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\CodexProxyDesktopLaunch-"+WindowsIdentity.GetCurrent().User.Value);remove=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\CodexProxyDesktopRemove-"+WindowsIdentity.GetCurrent().User.Value);exit=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\CodexProxyDesktopExit-"+WindowsIdentity.GetCurrent().User.Value);engine=new Engine();monitor=new NodeMonitor(engine);window=new MainWindow(engine,monitor);floating=new FloatingWindow(engine,monitor,()=>window.ShowManager());tray=new NotifyIcon{Icon=Program.Icon,Text="Codex 代理管理器 2.6",Visible=true};var menu=new ContextMenuStrip();menu.Items.Add("打开管理器",null,(s,a)=>window.ShowManager());menu.Items.Add("显示 / 隐藏悬浮窗",null,(s,a)=>window.ToggleFloating());menu.Items.Add("暂停 / 恢复守护",null,(s,a)=>{engine.Update(c=>c.Paused=!c.Paused);window.RefreshView();});menu.Items.Add("延后重启 10 分钟",null,(s,a)=>engine.Delay());menu.Items.Add("打开 Codex",null,(s,a)=>engine.Open());menu.Items.Add(new ToolStripSeparator());menu.Items.Add("退出程序（保留自启动）",null,(s,a)=>{try{engine.ExitSession();window.AllowExit();Application.Exit();}catch(Exception e){Files.Log("退出失败："+e.Message);}});tray.ContextMenuStrip=menu;tray.DoubleClick+=(s,a)=>window.ShowManager();tray.BalloonTipClicked+=(s,a)=>window.ShowManager();tick=new System.Windows.Forms.Timer{Interval=300};tick.Tick+=(s,a)=>{if(exit.WaitOne(0)){engine.ExitSession();window.AllowExit();Application.Exit();return;}if(remove.WaitOne(0)){window.RemoveProgram();return;}if(launch.WaitOne(0))engine.Open();if(show.WaitOne(0))window.ShowManager();var alert=monitor.Alert;if(alert!=null&&alert.Id!=lastAlert){lastAlert=alert.Id;if(engine.Config().NotifyProblems)TrayNotifications.Show(tray,7000,alert.Title,alert.Text,ToolTipIcon.Warning);}var v=engine.View;if(!String.IsNullOrEmpty(v.RestartDueUtc)&&v.RestartTicket!=lastTicket){lastTicket=v.RestartTicket;TrayNotifications.Show(tray,7000,"Codex 即将重启","代理需要更新，可打开管理器延后 10 分钟。",ToolTipIcon.Info);}if(v.ForceRequired&&!forceNotified){forceNotified=true;TrayNotifications.Show(tray,8000,"Codex 未正常退出","已保留进程。可在管理器中延后、手动退出或选择强制重启。",ToolTipIcon.Warning);}if(!v.ForceRequired)forceNotified=false;};window.Floating=floating;tick.Start();engine.Start();monitor.Start();if(Environment.GetCommandLineArgs().Contains("--open-codex"))engine.Open();if(engine.Config().ShowFloating)floating.Show();if(!background)window.Show();if(Environment.GetCommandLineArgs().Contains("--ready21"))TrayNotifications.Show(tray,10000,"Codex 代理管理器 2.6 已就绪","新界面、实时流量和桌面浮标已启用。自动恢复可在节点恢复页配置。",ToolTipIcon.Info);Application.ApplicationExit+=(s,a)=>{monitor.Dispose();floating.Close();engine.Dispose();tick.Stop();launch.Dispose();remove.Dispose();exit.Dispose();tray.Visible=false;tray.Dispose();window.AllowExit();window.Dispose();};}
 }
 static class TrayNotifications {
  static string Normalize(string value,string fallback,int limit){string text=new String((value??"").Where(c=>!Char.IsControl(c)||c=='\n').ToArray()).Trim();if(String.IsNullOrWhiteSpace(text))text=fallback;if(text.Length>limit){int length=limit;if(Char.IsHighSurrogate(text[length-1]))length--;text=text.Substring(0,length);}return text;}
  internal static string Title(string value){return Normalize(value,"Codex 代理管理器",63);}
  internal static string Text(string value){return Normalize(value,"代理检测状态已更新，请打开管理器查看详情。",255);}
  internal static bool Deliver(Action<int,string,string,ToolTipIcon> deliver,int timeout,string title,string text,ToolTipIcon icon){try{deliver(timeout,Title(title),Text(text),icon);return true;}catch(Exception error){Files.Log("托盘通知未显示，守护继续运行："+error.GetType().Name);return false;}}
  internal static bool Show(NotifyIcon tray,int timeout,string title,string text,ToolTipIcon icon){return Deliver((duration,caption,body,kind)=>tray.ShowBalloonTip(duration,caption,body,kind),timeout,title,text,icon);}
 }
 static class Program {
  public static readonly string Root=Environment.GetCommandLineArgs().Any(a=>a=="--test21"||a=="--preview21")?Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-runtime"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"CodexProxyDesktop");
  public static readonly string Exe=Path.Combine(Root,"CodexProxyDesktop.exe");
  public static readonly string Link=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Codex 代理管理器.lnk");
  public static Icon Icon{get{try{return Icon.ExtractAssociatedIcon(Exe);}catch{return SystemIcons.Application;}}}
  public static bool ShouldRunBackground(Settings settings,string session){return settings.ExitSessionKey!=session;}
  public static void CleanupBuild(){string build=Path.Combine(Root,"build");if(!Directory.Exists(build))return;if(Path.GetFullPath(build)!=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"CodexProxyDesktop","build")||(File.GetAttributes(build)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("构建目录不符合清理范围。");foreach(string name in new[]{"Core.cs","App.cs","app.ico","child-test.txt","self-test.txt","ui-preview.png"}){string path=Path.Combine(build,name);if(File.Exists(path)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("构建文件是链接，取消清理。");File.Delete(path);}}if(Directory.GetFileSystemEntries(build).Length>0)throw new InvalidOperationException("发现未识别文件，已保留这些文件。");Directory.Delete(build,false);Files.Log("构建临时文件已清理，没有保留备份。");}
  static string Quote(string value){return "'"+value.Replace("'","''")+"'";}
  public static void RemoveAfterExit(){string root=Path.GetFullPath(Root);if(root!=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"CodexProxyDesktop")||(File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("安装目录不符合删除范围。");string[] names={"CodexProxyDesktop.exe","settings.json","state.json","status.json","network-state.json","network-status.json","guard.log","settings.json.tmp","state.json.tmp","status.json.tmp","self-test.txt","ui-preview.png","child-test.txt"};string code="$ErrorActionPreference='Stop'; $root="+Quote(root)+"; if([IO.Path]::GetFullPath($root) -ne "+Quote(root)+"){throw 'Unexpected target'};for($i=0;$i -lt 30;$i++){if(-not (Get-Process -Id "+Process.GetCurrentProcess().Id+" -ErrorAction SilentlyContinue)){break};Start-Sleep -Seconds 1};if(Test-Path -LiteralPath "+Quote(Link)+"){Remove-Item -LiteralPath "+Quote(Link)+" -Force};if(Test-Path -LiteralPath $root){if(((Get-Item -LiteralPath $root -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'Unexpected link'};foreach($name in @("+String.Join(",",names.Select(Quote))+")){$file=Join-Path $root $name;for($i=0;$i -lt 10;$i++){try{if(Test-Path -LiteralPath $file){Remove-Item -LiteralPath $file -Force};break}catch{Start-Sleep -Seconds 2}}};if(@(Get-ChildItem -LiteralPath $root -Force).Count -eq 0){Remove-Item -LiteralPath $root -Force}}";var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"System32\WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(code))){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};using(var helper=Process.Start(info)){} }
  [STAThread]static int Main(string[] args){Directory.CreateDirectory(Root);ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;ServicePointManager.DefaultConnectionLimit=12;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
   if(args.Contains("--export-diagnostics24")){try{int index=Array.IndexOf(args,"--export-diagnostics24");using(var journal=new DiagnosticJournal(Path.Combine(Root,"diagnostics"),()=>Files.Load<Settings>("settings.json"),resumeCase:false)){journal.Export(args[index+1],DateTime.UtcNow.AddDays(-14),DateTime.UtcNow.AddSeconds(1));}return 0;}catch{return 1;}}
   if(args.Contains("--test21"))return Verification21.Run();
   if(args.Contains("--preview21"))return Verification21.Preview();
   if(args.Contains("--live-check21"))return Verification21.Live();
   if(args.Contains("--check-rule-route"))return RuleRepair.Run(false);
   if(args.Contains("--repair-rule-route"))return RuleRepair.Run(true);
   if(args.Contains("--hold-test")){Thread.Sleep(30000);return 0;}
   if(args.Contains("--child-probe")){File.WriteAllLines(args[1],new[]{Environment.GetEnvironmentVariable("HTTP_PROXY"),Environment.GetEnvironmentVariable("HTTPS_PROXY"),Environment.GetEnvironmentVariable("ALL_PROXY"),Environment.GetEnvironmentVariable("NO_PROXY"),String.Join(" ",args)});return 0;}
   if(args.Contains("--self-test"))return Tests.Run();
   if(args.Contains("--setup-launcher")){try{Startup.ProxyShortcut();return 0;}catch(Exception e){Files.Log("启动入口设置失败："+e.Message);return 1;}}
   if(args.Contains("--install")){try{Startup.Set(true);Startup.Shortcut();return 0;}catch(Exception e){Files.Log("安装失败："+e.Message);return 1;}}
   string suffix=WindowsIdentity.GetCurrent().User.Value;bool created;using(var mutex=new Mutex(true,"Local\\CodexProxyDesktop-"+suffix,out created))using(var show=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\CodexProxyDesktopShow-"+suffix)){
    if(!created){if(args.Contains("--open-codex")){using(var launch=EventWaitHandle.OpenExisting("Local\\CodexProxyDesktopLaunch-"+suffix))launch.Set();}else if(args.Contains("--exit-session")){using(var quit=EventWaitHandle.OpenExisting("Local\\CodexProxyDesktopExit-"+suffix))quit.Set();}else if(args.Contains("--uninstall")){using(var remove=EventWaitHandle.OpenExisting("Local\\CodexProxyDesktopRemove-"+suffix))remove.Set();}else if(!args.Contains("--background"))show.Set();return 0;}
    try{if(args.Contains("--exit-session"))return 0;if(args.Contains("--uninstall")){Startup.RestoreProxyShortcut();Startup.Remove();RemoveAfterExit();return 0;}Settings settings=Files.Load<Settings>("settings.json");string session=Native.SessionKey();bool explicitLaunch=args.Contains("--open-codex"),background=args.Contains("--background")||explicitLaunch;if(!explicitLaunch&&background&&!ShouldRunBackground(settings,session))return 0;if(!String.IsNullOrEmpty(settings.ExitSessionKey)){settings.ExitSessionKey="";Files.Save("settings.json",settings);}Application.Run(new DesktopContext(background,show));return 0;}catch(Exception e){Files.Log("程序异常："+e.Message);return 1;}finally{mutex.ReleaseMutex();}
   }
  }
 }
 static class Tests {
  static int passed;static readonly List<string> report=new List<string>();static void Check(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);passed++;report.Add("PASS: "+name);}
  public static int Run(){try{
   Check(ProxyTools.Normalize("127.0.0.1:7897")=="http://127.0.0.1:7897","Normalize HTTP");Check(ProxyTools.Normalize("[::1]:7897")=="http://[::1]:7897","Normalize IPv6");Check(ProxyTools.Normalize("http://user:secret@127.0.0.1:7897")==null,"Reject credentials");Check(ProxyTools.Normalize("socks5://127.0.0.1:7898")==null,"Reject SOCKS as HTTP");string pending="";int count=0;Check(ProxyTools.Stable(ref pending,ref count,"http://127.0.0.1:10001",3)==null,"Wait for stability");ProxyTools.Stable(ref pending,ref count,"http://127.0.0.1:10002",3);Check(count==1,"Port change resets stability");ProxyTools.Stable(ref pending,ref count,"",3);Check(count==0,"Outage resets stability");ProxyTools.Stable(ref pending,ref count,"http://127.0.0.1:10002",3);ProxyTools.Stable(ref pending,ref count,"http://127.0.0.1:10002",3);Check(ProxyTools.Stable(ref pending,ref count,"http://127.0.0.1:10002",3)!=null,"Three stable observations");
   using(var good=new Stub("200 Connection established"))using(var bad=new Stub("407 Proxy authentication required")){Check(ProxyTools.Connect("http://127.0.0.1:"+good.Port),"CONNECT succeeds");Check(!ProxyTools.Connect("http://127.0.0.1:"+bad.Port),"CONNECT rejection detected");}
   DateTime now=DateTime.UtcNow;var plan=new RestartPlan();plan.Queue("http://127.0.0.1:10001",now,60);Check(!plan.Ready(now.AddSeconds(59))&&plan.Ready(now.AddSeconds(60)),"Auto restart waits 60 seconds");int ticket=plan.Ticket;plan.Queue(plan.Proxy,now.AddSeconds(10),60);Check(plan.Ticket==ticket&&Files.Date(plan.DueUtc)==now.AddSeconds(60),"Repeated detection does not reset countdown");plan.Delay(now.AddSeconds(20));Check(!plan.Ready(now.AddMinutes(5))&&plan.Ready(now.AddSeconds(620)),"User postpones for 10 minutes");plan.Queue("http://127.0.0.1:10002",now.AddSeconds(25),60);Check(Files.Date(plan.DueUtc)==now.AddSeconds(620),"New port preserves user postponement");plan.Resume(now.AddSeconds(30),60);Check(Files.Date(plan.DueUtc)==now.AddSeconds(620),"Resume preserves manual postponement");var resumed=new RestartPlan();resumed.Queue("http://127.0.0.1:10003",now,60);resumed.Resume(now.AddMinutes(5),60);Check(!resumed.Ready(now.AddSeconds(359))&&resumed.Ready(now.AddSeconds(360)),"Resume provides fresh 60 second notice");plan.ForceRequired=true;Check(!plan.Ready(now.AddMinutes(30)),"Unclosed desktop waits for explicit force");plan.Clear();Check(!plan.Ready(now.AddMinutes(40)),"Cancelled restart cannot execute");
   string self=Process.GetCurrentProcess().MainModule.FileName;using(var held=Process.Start(new ProcessStartInfo(self,"--hold-test"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){Thread.Sleep(300);Check(!Engine.CloseDesktop(held,false,200)&&!held.HasExited,"Normal exit timeout preserves process");Check(Engine.CloseDesktop(held,true,100)&&held.HasExited,"Explicit force stops only test process");}
   var settings=new Settings{ExitSessionKey="session-A"};Check(!Program.ShouldRunBackground(settings,"session-A"),"Periodic task respects exit for current login");Check(Program.ShouldRunBackground(settings,"session-B"),"Next login starts normally");Check(!String.IsNullOrEmpty(Native.SessionKey()),"Current login session resolved");
   var h=new Health();Check(h.ServiceText().Contains("尚未检查"),"No false service-health claim before probe");h.Endpoints.Add(new EndpointHealth{Name="ChatGPT",Reachable=true,HttpStatus=403});h.Endpoints.Add(new EndpointHealth{Name="Codex",Reachable=false,Detail="超时"});Check(h.ServiceText().Contains("部分可达"),"Partial service reachability distinguished");h.Endpoints[1].Reachable=true;Check(h.ServiceText().Contains("登录状态由 Codex 确认"),"Reachable HTTPS does not claim authenticated success");
   string env=Environment.GetEnvironmentVariable("HTTP_PROXY",EnvironmentVariableTarget.User),childResult=Path.Combine(Program.Root,"build","child-test.txt");var info=ProxyTools.StartInfo(self,"http://127.0.0.1:12345",true);info.Arguments="--child-probe \""+childResult+"\" "+info.Arguments;using(var child=Process.Start(info))Check(child.WaitForExit(10000)&&child.ExitCode==0,"Hidden child launched");var lines=File.ReadAllLines(childResult);Check(lines[0]=="http://127.0.0.1:12345"&&lines[1]==lines[0]&&lines[2]==lines[0],"Child inherits all proxy variables");Check(lines[3]=="localhost,127.0.0.1,::1","Child localhost bypass");Check(lines[4].Contains("--proxy-server=http://127.0.0.1:12345"),"Child inherits browser proxy flag");Check(Environment.GetEnvironmentVariable("HTTP_PROXY",EnvironmentVariableTarget.User)==env,"Global environment preserved");Check(File.Exists(Native.CodexExe()),"Current Store executable resolved");Check(Native.Roots().Count>0,"Running Codex detected");Check(Startup.Enabled(),"Startup remains enabled");
   using(var engine=new Engine())using(var form=new MainWindow(engine)){engine.View=new ViewState{Mode="守护中",ObservedProxy="http://127.0.0.1:7897",AppliedProxy="http://127.0.0.1:7897",Source="系统代理",CodexPid=3792,Health=h,LastError="",RestartDueUtc=""};form.Text+="（界面验证）";form.Show();Application.DoEvents();var pause=(Button)typeof(MainWindow).GetField("pause",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(form);bool initial=engine.Config().Paused;pause.PerformClick();Check(engine.Config().Paused!=initial,"Pause button changes only pause state");pause.PerformClick();Check(engine.Config().Paused==initial,"Resume restores pause state");Check(Startup.Enabled(),"Pause and resume leave startup enabled");h.Tcp=true;h.Tunnel=true;form.RefreshView();foreach(var link in Descendants(form).OfType<LinkLabel>())Check(link.Parent.ClientRectangle.Contains(link.Bounds),"Visible link: "+link.Text+" bounds="+link.Bounds+" parent="+link.Parent.ClientRectangle);using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(Path.Combine(Program.Root,"build","ui-preview.png"),System.Drawing.Imaging.ImageFormat.Png);}form.AllowExit();form.Close();}
   report.Add("Passed "+passed+" checks");File.WriteAllLines(Path.Combine(Program.Root,"build","self-test.txt"),report,new UTF8Encoding(false));return 0;
  }catch(Exception e){report.Add(e.ToString());File.WriteAllLines(Path.Combine(Program.Root,"build","self-test.txt"),report,new UTF8Encoding(false));return 1;}}
  static IEnumerable<Control> Descendants(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(Control next in Descendants(child))yield return next;}}
  sealed class Stub:IDisposable {readonly TcpListener server;readonly Thread worker;readonly string response;volatile bool done;public int Port;public Stub(string status){response="HTTP/1.1 "+status+"\r\n\r\n";server=new TcpListener(IPAddress.Loopback,0);server.Start();Port=((IPEndPoint)server.LocalEndpoint).Port;worker=new Thread(Serve){IsBackground=true};worker.Start();}void Serve(){while(!done)try{using(var client=server.AcceptTcpClient()){client.ReceiveTimeout=1500;var stream=client.GetStream();byte[] data=new byte[4096];if(stream.Read(data,0,data.Length)>0){byte[] responseBytes=Encoding.ASCII.GetBytes(response);stream.Write(responseBytes,0,responseBytes.Length);}}}catch{}}public void Dispose(){done=true;server.Stop();worker.Join(2000);}}
 }
